pub fn MaxDifference(a: Vec<i64>) -> i64 {
    assert!(a.len() >= 2, "Input array must have at least two elements");

    // Initialize min and max with the first element
    let mut iter = a.into_iter();
    let first = iter.next().unwrap();
    let (mut min_val, mut max_val) = (first, first);

    // Scan through the rest of the elements
    for x in iter {
        if x < min_val {
            min_val = x;
        }
        if x > max_val {
            max_val = x;
        }
    }

    // The maximum difference is max - min
    max_val - min_val
}

